const paidOrder = async (h: any, id: string) => {
  await h.create(id); await h.addItem(id); await h.place(id);
  const e = (await h.pendingEffects()).find((x: any) => x.from === id);
  await h.completeEffect(e.id, 'ok');
};

test('hold and release', async () => {
  const h = await fresh();
  assert.equal((await h.hold('x')).ok, false);
  assert.equal((await h.release('x')).ok, false);
  await h.create('a');
  assert.equal((await h.hold('a')).ok, false);
  assert.equal((await h.release('a')).ok, false);
  await paidOrder(h, 'b');
  assert.equal((await h.release('b')).ok, false);
  assert.equal((await h.hold('b')).ok, true);
  assert.equal((await h.hold('b')).ok, false);
  assert.deepEqual(await h.order('b'), view('paid', 1, 1, 0, true));
  assert.equal((await h.ship('b')).ok, false);
  assert.equal((await h.release('b')).ok, true);
  assert.deepEqual(await h.order('b'), view('paid', 1, 1, 0, false));
  assert.equal((await h.ship('b')).ok, true);
  assert.equal((await h.hold('b')).ok, false);
  assert.deepEqual(await h.order('b'), view('shipped', 1, 1, 0, false));
});

test('cancel a held order', async () => {
  const h = await fresh();
  await paidOrder(h, 'a');
  await h.hold('a');
  assert.equal((await h.cancel('a')).ok, true);
  assert.deepEqual(await h.order('a'), view('cancelled', 1, 1, 1, false));
  assert.equal((await h.release('a')).ok, false);
  assert.equal((await h.hold('a')).ok, false);
});

test('hold refused while placed, cancelling, declined', async () => {
  const h = await fresh();
  await h.create('a'); await h.addItem('a'); await h.place('a');
  assert.equal((await h.hold('a')).ok, false);
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'failed');
  assert.equal((await h.hold('a')).ok, false);
  await h.retryPayment('a'); await h.cancel('a');
  assert.equal((await h.hold('a')).ok, false);
  assert.deepEqual(await h.order('a'), view('cancelling', 1, 2));
});

