import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const fresh = async () => (await (createHost as any)()) as any;
const view = (status: string, items: number, charges = 0, refunds = 0) => ({ status, items, charges, refunds });

test('create, unknown ids, duplicates', async () => {
  const h = await fresh();
  assert.equal(await h.order('a'), null);
  assert.equal((await h.addItem('a')).ok, false);
  assert.equal(await h.order('a'), null);
  assert.deepEqual(await h.create('a'), { ok: true });
  assert.equal((await h.create('a')).ok, false);
  assert.deepEqual(await h.order('a'), view('draft', 0));
  assert.deepEqual(await h.pendingEffects(), []);
});

test('items bounded 0..3', async () => {
  const h = await fresh();
  await h.create('a');
  assert.equal((await h.removeItem('a')).ok, false);
  for (let i = 0; i < 3; i++) assert.equal((await h.addItem('a')).ok, true);
  assert.equal((await h.addItem('a')).ok, false);
  assert.equal((await h.removeItem('a')).ok, true);
  assert.deepEqual(await h.order('a'), view('draft', 2));
});

test('place, charge ok, ship', async () => {
  const h = await fresh();
  await h.create('a');
  assert.equal((await h.place('a')).ok, false);
  await h.addItem('a'); await h.addItem('a');
  assert.equal((await h.place('a')).ok, true);
  assert.equal((await h.place('a')).ok, false);
  assert.equal((await h.ship('a')).ok, false);
  assert.equal((await h.addItem('a')).ok, false);
  const effs = await h.pendingEffects();
  assert.equal(effs.length, 1);
  assert.equal(effs[0].from, 'a');
  assert.equal(effs[0].kind, 'payment.charge');
  assert.deepEqual(effs[0].data, { amount: 2 });
  assert.deepEqual(await h.order('a'), view('placed', 2, 1));
  await h.completeEffect(effs[0].id, 'ok');
  assert.deepEqual(await h.pendingEffects(), []);
  assert.deepEqual(await h.order('a'), view('paid', 2, 1));
  assert.equal((await h.ship('a')).ok, true);
  assert.deepEqual(await h.order('a'), view('shipped', 2, 1));
  for (const m of ['addItem', 'removeItem', 'place', 'ship', 'cancel']) assert.equal((await h[m]('a')).ok, false);
});

const ALL = ['addItem', 'removeItem', 'place', 'ship', 'cancel', 'retryPayment'];

test('charge declined, retried, failed', async () => {
  const h = await fresh();
  await h.create('a'); await h.addItem('a'); await h.place('a');
  assert.equal((await h.retryPayment('a')).ok, false);
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'failed');
  assert.deepEqual(await h.order('a'), view('declined', 1, 1));
  for (const m of ALL.filter((m) => m !== 'retryPayment')) assert.equal((await h[m]('a')).ok, false);
  assert.deepEqual(await h.order('a'), view('declined', 1, 1));
  assert.equal((await h.retryPayment('a')).ok, true);
  assert.equal((await h.retryPayment('a')).ok, false);
  assert.deepEqual(await h.order('a'), view('placed', 1, 2));
  const effs = await h.pendingEffects();
  assert.equal(effs.length, 1);
  assert.notEqual(effs[0].id, e.id);
  assert.equal(effs[0].kind, 'payment.charge');
  assert.deepEqual(effs[0].data, { amount: 1 });
  await h.completeEffect(effs[0].id, 'failed');
  assert.deepEqual(await h.order('a'), view('failed', 1, 2));
  assert.deepEqual(await h.pendingEffects(), []);
  for (const m of ALL) assert.equal((await h[m]('a')).ok, false);
});

test('retry succeeds, ship, unknown retry', async () => {
  const h = await fresh();
  assert.equal((await h.retryPayment('x')).ok, false);
  await h.create('a'); await h.addItem('a'); await h.addItem('a'); await h.place('a');
  await h.completeEffect((await h.pendingEffects())[0].id, 'failed');
  await h.retryPayment('a');
  await h.completeEffect((await h.pendingEffects())[0].id, 'ok');
  assert.deepEqual(await h.order('a'), view('paid', 2, 2));
  assert.equal((await h.retryPayment('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, true);
  assert.deepEqual(await h.order('a'), view('cancelled', 2, 2, 1));
});

test('cancel while placed: charge ok refunds', async () => {
  const h = await fresh();
  await h.create('a'); await h.addItem('a'); await h.addItem('a'); await h.place('a');
  assert.equal((await h.cancel('a')).ok, true);
  assert.deepEqual(await h.order('a'), view('cancelling', 2, 1));
  for (const m of ALL) assert.equal((await h[m]('a')).ok, false);
  assert.deepEqual(await h.order('a'), view('cancelling', 2, 1));
  const [e] = await h.pendingEffects();
  assert.equal(e.kind, 'payment.charge');
  await h.completeEffect(e.id, 'ok');
  assert.deepEqual(await h.order('a'), view('cancelled', 2, 1, 1));
  const effs = await h.pendingEffects();
  assert.equal(effs.length, 1);
  assert.equal(effs[0].kind, 'payment.refund');
  assert.equal(effs[0].from, 'a');
  for (const m of ALL) assert.equal((await h[m]('a')).ok, false);
});

test('cancel while placed: charge failed, no refund', async () => {
  const h = await fresh();
  await h.create('a'); await h.addItem('a'); await h.place('a');
  await h.cancel('a');
  await h.completeEffect((await h.pendingEffects())[0].id, 'failed');
  assert.deepEqual(await h.order('a'), view('cancelled', 1, 1, 0));
  assert.deepEqual(await h.pendingEffects(), []);
});

test('cancel during retry: failed second charge cancels', async () => {
  const h = await fresh();
  await h.create('a'); await h.addItem('a'); await h.place('a');
  await h.completeEffect((await h.pendingEffects())[0].id, 'failed');
  assert.equal((await h.cancel('a')).ok, false);
  await h.retryPayment('a');
  assert.equal((await h.cancel('a')).ok, true);
  await h.completeEffect((await h.pendingEffects())[0].id, 'failed');
  assert.deepEqual(await h.order('a'), view('cancelled', 1, 2, 0));
});

test('retry refused on draft and paid', async () => {
  const h = await fresh();
  await h.create('a');
  assert.equal((await h.retryPayment('a')).ok, false);
  await h.addItem('a'); await h.place('a');
  await h.completeEffect((await h.pendingEffects())[0].id, 'ok');
  assert.equal((await h.retryPayment('a')).ok, false);
  assert.deepEqual(await h.order('a'), view('paid', 1, 1));
});

test('cancel draft and paid', async () => {
  const h = await fresh();
  await h.create('d');
  assert.equal((await h.cancel('d')).ok, true);
  assert.deepEqual(await h.order('d'), view('cancelled', 0));
  assert.equal((await h.cancel('d')).ok, false);
  await h.create('p'); await h.addItem('p'); await h.place('p');
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'ok');
  assert.equal((await h.cancel('p')).ok, true);
  assert.deepEqual(await h.order('p'), view('cancelled', 1, 1, 1));
  assert.equal((await h.cancel('p')).ok, false);
  assert.equal((await h.ship('p')).ok, false);
  const pending = await h.pendingEffects();
  assert.equal(pending.length, 1);
  assert.equal(pending[0].kind, 'payment.refund');
  await h.completeEffect(pending[0].id, 'failed');
  assert.deepEqual(await h.pendingEffects(), []);
  assert.deepEqual(await h.order('p'), view('cancelled', 1, 1, 1));
});
